package io.github.diodeme.ji.error;

/** Public exception carrying the complete transport-neutral JI error contract. */
public final class JiException extends RuntimeException {
    private static final long serialVersionUID = 1L;
    private final transient JiError error;

    public JiException(JiError error) {
        super(error.code().code());
        this.error = error;
    }

    public JiException(JiError error, Throwable cause) {
        super(error.code().code(), cause);
        this.error = error;
    }

    public JiError error() {
        return error;
    }
}
